import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.D9ghT4bC.js";const y=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"Privacy-Policy.md","filePath":"Privacy-Policy.md"}'),i={name:"Privacy-Policy.md"};function s(n,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p>This policy applies to the community services run for UncivCN: this documentation site, the community download server and the community multiplayer servers. They are built and maintained by volunteers of the UncivCN community as a personal effort. They are <strong>not</strong> operated by, affiliated with or endorsed by the Unciv project or its developers — the game itself is made by the upstream team at <a href="https://github.com/yairm210/Unciv" target="_blank" rel="noreferrer">https://github.com/yairm210/Unciv</a>. The maintainer of these services is the data controller.</p><p>Questions, deletion and export requests: <a href="https://qm.qq.com/q/j92c3iUnZ0" target="_blank" rel="noreferrer">QQ group</a> or <a href="https://github.com/AutumnPizazz/Unciv/issues" target="_blank" rel="noreferrer">GitHub Issues</a>.</p><h2 id="what-we-store" tabindex="-1">What we store <a class="header-anchor" href="#what-we-store" aria-label="Permalink to &quot;What we store&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data</th><th>Why we need it</th><th>How long</th></tr></thead><tbody><tr><td>Player ID and password hash</td><td>Signing in to multiplayer servers. The ID is generated by your game client, the password is stored only as a salted hash</td><td>Until you ask us to delete the account</td></tr><tr><td>Last active time</td><td>Showing who is online, cleaning up unused data</td><td>Until account deletion</td></tr><tr><td>IP address</td><td>Abuse protection and rate limiting. By default only the network part is kept (IPv4 <code>/24</code>, IPv6 <code>/48</code>)</td><td>30 days by default, then cleared automatically. Server owners can also set it to keep nothing at all</td></tr><tr><td>Multiplayer saves</td><td>So the other players of your game can fetch the current turn</td><td>Games nobody has played for a long time are archived (encrypted) elsewhere when the server runs out of space; archived games can still be restored, or deleted on request</td></tr><tr><td>Access logs (IP, user agent)</td><td>Security and troubleshooting</td><td>Kept short on the server, not shared</td></tr></tbody></table><p>Passwords are stored as <code>scrypt</code> hashes with a random salt per account: nobody, including the administrator, can read them back — an administrator can only reset a password.</p><h2 id="what-we-don-t-store" tabindex="-1">What we don&#39;t store <a class="header-anchor" href="#what-we-don-t-store" aria-label="Permalink to &quot;What we don&#39;t store&quot;">​</a></h2><ul><li>No real name, ID number, phone number or e-mail address. The services never require identity documents.</li><li>No payment data and no advertising identifiers: these services are free and non-commercial.</li><li>No data is sold or shared with third parties, and the documentation site does not run analytics or tracking.</li></ul><h2 id="your-choices" tabindex="-1">Your choices <a class="header-anchor" href="#your-choices" aria-label="Permalink to &quot;Your choices&quot;">​</a></h2><ul><li><strong>Use another server</strong>: in the game, open Options → Advanced and set your own multiplayer server URL. You can also import your own player ID there.</li><li><strong>Delete or export your data</strong>: ask in the QQ group or open an issue; we will hand out your saves and delete your account and data.</li><li>Everything else the game stores (settings, single-player saves) stays on your device. The servers only ever see what the multiplayer client uploads.</li><li>If a minor registered without a guardian&#39;s consent, contact us and we will delete the account.</li></ul><h2 id="third-parties" tabindex="-1">Third parties <a class="header-anchor" href="#third-parties" aria-label="Permalink to &quot;Third parties&quot;">​</a></h2><ul><li>The documentation site is hosted on GitHub Pages, so visiting it also involves GitHub&#39;s servers.</li><li>Mods and installers can be downloaded from the mirror you configure in the game; those services have their own policies.</li><li>Depending on availability, servers may be hosted outside mainland China; data is processed where the server runs.</li></ul><h2 id="security-and-limits" tabindex="-1">Security and limits <a class="header-anchor" href="#security-and-limits" aria-label="Permalink to &quot;Security and limits&quot;">​</a></h2><p>We use HTTPS, hashed passwords and access controls, but these are volunteer services provided &quot;as is&quot;. We cannot promise unlimited availability, absolute confidentiality or that data will never be lost — keep your own backups of saves you care about.</p><p>Changes to this policy are described in the <a href="/Unciv/UncivCN/Changelog.html">changelog</a>, and the <a href="/Unciv/Terms-of-Service.html">Terms of Service</a> describe how the services may be used.</p>',15)])])}const m=t(i,[["render",s]]);export{y as __pageData,m as default};
